/// <summary>
/// Sales order process helper class.
/// </summary>
public class METSalesOrderProcessHelper
{
}

Method.Source:
/// <summary>
/// Picking list registration of th sales order.
/// </summary>
/// <param name = "_salesTable"></param>
/// <param name = "_salesLineReferences"></param>
/// <returns></returns>
public WMSPickingRouteID pickingListRegistrationForSO(SalesTable _salesTable, container _salesLineReferences)
{
    SalesParmLine            salesParmLine;
    SalesFormLetter          salesFormLetter;
    WMSPickingRoute          wmsPickingRoute;
    FormletterOutputContract outputContract;

    salesFormLetter = SalesFormLetter::construct(DocumentStatus::PickingList);

    salesFormLetter.salesTable(_salesTable);
    salesFormLetter.initParmSalesTable(salesFormLetter.salesTable());
    salesFormLetter.transDate(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
    salesFormLetter.specQty(SalesUpdate::All);
    salesFormLetter.proforma(salesFormLetter.salesParmUpdate().Proforma);
    salesFormLetter.printFormLetter(salesFormLetter.printFormLetter());
    salesFormLetter.printCODLabel(NoYes::No);
    salesFormLetter.printShippingLabel(NoYes::No);
    salesFormLetter.usePrintManagement(false);
    salesFormLetter.creditRemaining(salesFormLetter.creditRemaining());

    salesFormLetter.createParmUpdateFromParmUpdateRecord(
        SalesFormletterParmData::initSalesParmUpdateFormletter(
        salesFormLetter.documentStatus(), salesFormLetter.pack(), true, false, false));

    salesFormLetter.initParameters(salesFormLetter.salesParmUpdate(), Printout::Current);
    salesFormLetter.initLinesQuery();

    //Delete unwanted records in SalesParmLine
    while select forupdate salesParmLine
        where salesParmLine.ParmId == salesFormLetter.parmId()
    {
        if (conFind(_salesLineReferences, salesParmLine.InventTransId) == 0)
        {
            salesParmLine.delete();
        }
    }

    salesFormLetter.run();

    outputContract  = salesFormLetter.getOutputContract();
    wmsPickingRoute = outputContract.parmJournal();

    return wmsPickingRoute.pickingRouteID;
}

/// <summary>
/// Create the Purchase order.
/// </summary>
/// <param name = "_salesTable"></param>
/// <param name = "_salesLine"></param>
public static void createPOForIntercompanyFulfillment(SalesTable _salesTable, SalesLine _salesLine)
{
    boolean             isIncluded = NoYes::Yes;
    InventTable         inventTable;
    TmpPurchLinePrice   tmpPurchLinePrice;

    //Insert <c>SalesLine</c> record into <c>TmpPurchLinePrice</c>.
    tmpPurchLinePrice.clear();

    tmpPurchLinePrice.SalesId           = _salesLine.SalesId;
    tmpPurchLinePrice.LineNum           = _salesLine.LineNum;
    tmpPurchLinePrice.PurchQty          = _salesLine.SalesQty;
    tmpPurchLinePrice.Included          = isIncluded;

    select firstonly PrimaryVendorId from inventTable
        where inventTable.ItemId == _salesLine.ItemId
        && inventTable.PrimaryVendorId != '';

    if (inventTable.RecId)
    {
        tmpPurchLinePrice.AccountNum        = inventTable.PrimaryVendorId;
        tmpPurchLinePrice.SalesLineRefRecId = _salesLine.RecId;

        tmpPurchLinePrice.insert();

        //Create the purchase order from the extracted sales order.
        PurchCreateFromSalesOrder purchCreateFromSalesOrder = PurchCreateFromSalesOrder::newPurchCreateFromSalesOrder(TradeLineDlvType::None);
        purchCreateFromSalesOrder.parmSalesTable(_salesTable);
        purchCreateFromSalesOrder.parmCallerRecord(_salesTable);
        purchCreateFromSalesOrder.parmTmpPurchLinePrice(tmpPurchLinePrice);
        purchCreateFromSalesOrder.runOperation();
    }

}
